// Парсер всех рецептов водок из исторического документа
// Sparse vectors убраны — BGE-M3 генерирует их автоматически
console.log('=== ПАРСИНГ ВСЕХ РЕЦЕПТОВ ===');

try {
  const inputData = $input.first();

  if (!inputData?.json?.content) {
    return [{ json: { error: 'No content field found' } }];
  }

  const fullText = inputData.json.content;
  console.log(`Полный текст: ${fullText.length} символов`);

  function parseAllWaterRecipes(text) {
    const recipes = [];

    try {
      console.log('Поиск всех рецептов в документе...');

      const mainPattern = /\*\*(\d+)\.\s*([^*\n]+?)\*\*\s*([\s\S]*?)(?=\*\*\d+\.|$)/g;
      let match;
      let foundCount = 0;

      while ((match = mainPattern.exec(text)) !== null && foundCount < 300) {
        const number = parseInt(match[1]);
        let name = match[2].trim().replace(/\.$/, '');
        let content = match[3].trim();

        content = content.replace(/^\s*\n+/, '');

        if (name.includes('ГЛАВА') || 
            name.includes('Водки тминные') || 
            name.includes('Водки анисовые') ||
            name.includes('Водки ировые') ||
            name.includes('Водки померанцевые') ||
            name.includes('Водки фенхельные') ||
            name.includes('Водки розмариновые') ||
            name.includes('Полынные водки') ||
            name.includes('Водки из кудрявой мяты') ||
            name.includes('Лимонные водки') ||
            name.includes('Водки коричные') ||
            name.includes('Водки можжевеловые') ||
            name.includes('Водки мелиссные') ||
            name.includes('Водки дягилевые') ||
            name.includes('Водки девясильные') ||
            name.includes('Водки гвоздичные') ||
            name.includes('Водки цитварные') ||
            name.includes('Водки карминативные') ||
            name.includes('Водки желудочные') ||
            name.includes('Грудные водки') ||
            name.includes('Персиковые водки') ||
            name.includes('Водки, называемые крамбамбули') ||
            name.includes('Мастичные водки') ||
            name.includes('Водки от колики') ||
            name.includes('Водки укрепительные') ||
            name.includes('Водки ореховые') ||
            name.includes('Водки Игуменские') ||
            name.includes('Розолии') ||
            name.includes('Воздушные водки') ||
            name.includes('Кардамонные водки') ||
            name.includes('Водки для здоровья') ||
            name.includes('Ратафии') ||
            name.includes('Христофлеты') ||
            name.includes('Водки хлебные') ||
            name.includes('Водки оранжевые') ||
            name.includes('Водки серебряные') ||
            name.includes('Водки золотые') ||
            name.includes('Водки горькия') ||
            content.length < 100) {
          continue;
        }

        if (name.length > 3 && content.length > 50) {
          recipes.push({
            id: `${number}`,
            number: number,
            name: name,
            content: content,
            full_text: `${name}\n\n${content}`
          });

          console.log(`Найден рецепт ${number}: "${name}"`);
          foundCount++;
        }
      }

      console.log(`Основным паттерном найдено: ${recipes.length} рецептов`);

      if (recipes.length < 100) {
        console.log('Поиск дополнительных рецептов...');

        const additionalPattern = /^(\d+)\.\s*([А-ЯЁа-яё][^\n]{10,100}?)\.\s*$([\s\S]*?)(?=^\d+\.\s*[А-ЯЁа-яё]|$)/gm;
        let additionalMatch;

        while ((additionalMatch = additionalPattern.exec(text)) !== null) {
          const number = parseInt(additionalMatch[1]);
          const name = additionalMatch[2].trim();
          const content = additionalMatch[3].trim();

          if (!recipes.some(r => r.number === number) && content.length > 100) {
            recipes.push({
              id: `recipe_${number}`,
              number: number,
              name: name,
              content: content,
              full_text: `${name}\n\n${content}`
            });

            console.log(`Дополнительно найден рецепт ${number}: "${name}"`);
          }
        }
      }

    } catch (parseError) {
      console.log('Ошибка парсинга:', parseError.message);
    }

    return recipes;
  }

  const allRecipes = parseAllWaterRecipes(fullText);
  console.log(`ВСЕГО НАЙДЕНО РЕЦЕПТОВ: ${allRecipes.length}`);

  if (allRecipes.length === 0) {
    return [{ json: { 
      error: 'No recipes found',
      document_length: fullText.length,
      text_sample: fullText.substring(0, 2000)
    }}];
  }

  allRecipes.sort((a, b) => a.number - b.number);

  console.log('=== ПАРСИНГ ЗАВЕРШЕН ===');
  console.log(`Обработано рецептов: ${allRecipes.length}`);

  return allRecipes.map(recipe => ({ json: recipe }));

} catch (globalError) {
  console.log('КРИТИЧЕСКАЯ ОШИБКА:', globalError.message);
  return [{ json: { 
    error: 'Critical parsing error',
    message: globalError.message,
    stack: globalError.stack
  }}];
}

// Code1: Подготовка текста для BGE-M3 embed/qdrant
const recipe = $input.first().json;

const fullText = `Рецепт: ${recipe.name}\n\nСодержание: ${recipe.content}`;

const MAX_CHARS = 16000;
let embeddingText = fullText;

if (fullText.length > MAX_CHARS) {
  const truncated = fullText.substring(0, MAX_CHARS);
  const lastSpace = truncated.lastIndexOf(' ');
  embeddingText = lastSpace > MAX_CHARS * 0.9
    ? truncated.substring(0, lastSpace) + '...'
    : truncated + '...';
  console.log(`Текст обрезан: ${fullText.length} → ${embeddingText.length} символов`);
}

return [{
  json: {
    embed_text: embeddingText,
    recipe_data: {
      id: recipe.id,
      number: recipe.number,
      name: recipe.name,
      content: recipe.content,
      full_text: recipe.full_text
    }
  }
}];

// Combining vectors: BGE-M3 dense + sparse → Qdrant point
const response = $input.last().json;
const recipe = $('Code1').first().json.recipe_data;

const dense = response.results[0].dense;
const sparse = response.results[0].sparse;

console.log(`Рецепт: ${recipe.name}`);
console.log(`Dense: ${dense.length} dims, Sparse: ${sparse.indices.length} tokens`);

const point = {
  id: Math.abs(recipe.number * 10000 + Date.now() % 10000),
  vector: {
    dense: dense,
    sparse: sparse
  },
  payload: {
    recipe_id: recipe.id,
    recipe_number: recipe.number,
    recipe_name: recipe.name,
    content: recipe.content,
    full_text: recipe.full_text,
    content_length: recipe.content?.length || 0,
    name_lower: recipe.name?.toLowerCase() || '',
    is_vodka: recipe.name?.toLowerCase().includes('водка') || false,
    is_rozolia: recipe.name?.toLowerCase().includes('розолия') || false,
    is_ratafia: recipe.name?.toLowerCase().includes('ратафия') || false,
    created_at: new Date().toISOString(),
    vector_dimension: dense.length,
    sparse_token_count: sparse.indices.length,
    source: 'breiten3vodka'
  }
};

console.log(`✅ Point создан: ID=${point.id}, рецепт "${recipe.name}"`);

return [{ json: { points: [point] } }];
